	l, err := newLexicon(wordnet.Data{Lemmas: []wordnet.Lexeme{a, b, c}, Edges: []wordnet.Edge{{From: a, To: b, ID: "a:00000001:01+n:00000002:01"}, {From: b, To: c, ID: "n:00000002:01+a:00000003:01"}}})
