		delete(files, name)
		if _, err := loadLexicon(files); !errors.Is(err, ErrLexiconUnavailable) {
			t.Fatalf("missing %s accepted", name)
		}
		files[name] = &fstest.MapFile{Data: []byte("tampered")}
		if _, err := loadLexicon(files); !errors.Is(err, ErrLexiconUnavailable) {
